"""Deterministic Semantic Discovery & Matching Engine for Phase 4.

Uses rule-based heuristics, token similarity, domain terminology aliasing,
and profiling metadata (data types, uniqueness, null ratios) to propose
explainable, confidence-scored property-to-column mappings.
Zero LLM or external AI dependencies.
"""

import re
from dataclasses import dataclass
from typing import Any

from corbel.domains.ontology.models import Property, PropertyType


@dataclass
class CandidateSuggestion:
    """Explainable semantic mapping candidate generated by the deterministic matcher."""

    property_id: str
    property_name: str
    column_name: str
    confidence: float
    is_compatible: bool
    explanation: str


# Procure-to-Pay (P2P) Domain Synonym & Concept Alias Dictionary
P2P_SYNONYM_GROUPS: list[set[str]] = [
    # Invoice identifiers
    {"invoice_id", "inv_id", "invoiceno", "invoice_no", "invoice_number", "bill_id", "bill_number", "inv_num", "bill_no"},
    # Purchase Order identifiers
    {"po_id", "po_number", "po_no", "ponumber", "order_id", "order_number", "order_no", "purchase_order_id", "purchase_order_number"},
    # Supplier identifiers
    {"supplier_id", "vendor_id", "vendor_no", "vendor_code", "supplier_no", "supplier_code", "vendor_num", "partner_id"},
    # Supplier names
    {"supplier_name", "vendor_name", "vendor", "supplier", "company_name", "vendor_title"},
    # Monetary amounts
    {"invoice_amount", "total_amount", "amount", "inv_amt", "gross_amount", "net_amount", "total_spend", "spend", "line_total"},
    # Invoicing dates
    {"invoice_date", "inv_date", "bill_date", "billing_date", "doc_date", "created_date"},
    # Due dates
    {"due_date", "payment_due_date", "inv_due_date", "net_due_date", "terms_date"},
    # Goods receipt identifiers
    {"receipt_id", "gr_id", "goods_receipt_id", "delivery_note", "packing_slip", "receipt_no", "shipment_id"},
    # Delivery dates
    {"delivery_date", "receipt_date", "received_date", "goods_receipt_date", "actual_delivery_date"},
    # Quantities
    {"quantity_received", "qty_received", "quantity", "qty", "delivered_quantity", "shipped_qty"},
    # Currencies
    {"currency", "curr", "currency_code", "curr_code"},
    # Statuses
    {"status", "invoice_status", "order_status", "state", "doc_status", "lifecycle_state"},
]


def _normalize_name(name: str) -> str:
    """Normalize identifier by converting to lowercase and stripping punctuation/prefixes."""
    clean = name.strip().lower()
    # Replace separators with underscore
    clean = re.sub(r"[\s\-\.]+", "_", clean)
    # Remove common technical prefixes
    clean = re.sub(r"^(col_|tbl_|field_|src_)", "", clean)
    return clean


def _tokenize(name: str) -> set[str]:
    """Tokenize identifier into individual conceptual word tokens."""
    normalized = _normalize_name(name)
    # Split camelCase and snake_case
    tokens = re.findall(r"[a-z0-9]+", normalized)
    # Remove generic single-letter noise
    return {t for t in tokens if len(t) > 1}


def _check_alias_match(prop_name: str, col_name: str) -> bool:
    """Check if property name and column name belong to the same P2P synonym group."""
    norm_prop = _normalize_name(prop_name)
    norm_col = _normalize_name(col_name)
    if norm_prop == norm_col:
        return True

    return any(norm_prop in group and norm_col in group for group in P2P_SYNONYM_GROUPS)


def _compute_type_compatibility(
    prop_type: str,
    col_type: str,
    col_profile: dict[str, Any] | None,
) -> tuple[float, str]:
    """Evaluate deterministic data type compatibility between ontology property and dataset column.

    Returns (compatibility_weight, explanation_fragment).
    """
    col_type_upper = col_type.upper()
    prop_type_upper = prop_type.upper()

    if prop_type_upper == PropertyType.NUMBER.value:
        if col_type_upper in ("INTEGER", "FLOAT", "NUMBER"):
            return 1.0, f"Compatible numeric types ({col_type_upper} -> {prop_type_upper})"
        if col_type_upper == "STRING":
            # Check if column profile indicates numeric stats
            if col_profile and col_profile.get("numeric_stats"):
                return 0.7, "STRING column contains parsed numeric values"
            return 0.2, "STRING column may require numeric casting"
        return 0.0, f"Incompatible type: {col_type_upper} cannot map to NUMBER"

    if prop_type_upper == PropertyType.DATETIME.value:
        if col_type_upper in ("DATETIME", "DATE"):
            return 1.0, f"Compatible temporal types ({col_type_upper} -> {prop_type_upper})"
        if col_type_upper == "STRING":
            return 0.6, "STRING column may contain formatted date strings"
        return 0.0, f"Incompatible type: {col_type_upper} cannot map to DATETIME"

    if prop_type_upper == PropertyType.BOOLEAN.value:
        if col_type_upper == "BOOLEAN":
            return 1.0, "Compatible boolean types"
        return 0.3, f"Potential boolean flag from {col_type_upper}"

    if prop_type_upper == PropertyType.STRING.value:
        if col_type_upper == "STRING":
            return 1.0, "Compatible string types"
        return 0.85, f"Column type {col_type_upper} safely converts to STRING"

    if prop_type_upper == PropertyType.ENUM.value:
        if col_type_upper == "STRING":
            return 1.0, "Compatible string enum"
        return 0.5, f"Column {col_type_upper} mapped to ENUM"

    return 0.5, f"Standard conversion ({col_type_upper} -> {prop_type_upper})"


class SemanticMatcher:
    """Deterministic matcher proposing explainable candidate mappings between

    dataset columns and ontology properties.
    """

    @classmethod
    def match_column_to_property(
        cls,
        prop: Property,
        column_meta: dict[str, Any],
        column_profile: dict[str, Any] | None = None,
    ) -> CandidateSuggestion | None:
        """Score the semantic match between a dataset column and an ontology property."""
        col_name = column_meta.get("name", "")
        col_type = column_meta.get("data_type", "STRING")

        norm_prop = _normalize_name(prop.name)
        norm_col = _normalize_name(col_name)

        # 1. Type Compatibility
        type_weight, type_expl = _compute_type_compatibility(
            prop.data_type, col_type, column_profile
        )

        if type_weight <= 0.0:
            return None  # Incompatible type: do not suggest

        # 2. Name & Token Similarity
        name_score = 0.0
        match_reason = ""

        if norm_prop == norm_col:
            name_score = 1.0
            match_reason = f"Exact name match ('{col_name}' == '{prop.name}')"
        elif _check_alias_match(prop.name, col_name):
            name_score = 0.92
            match_reason = f"Known domain alias match ('{col_name}' -> '{prop.name}')"
        else:
            # Token overlap (Jaccard similarity)
            prop_tokens = _tokenize(prop.name)
            col_tokens = _tokenize(col_name)
            if prop_tokens and col_tokens:
                intersection = prop_tokens.intersection(col_tokens)
                union = prop_tokens.union(col_tokens)
                jaccard = len(intersection) / len(union) if union else 0.0
                if jaccard >= 0.5:
                    name_score = 0.60 + (jaccard * 0.25)
                    match_reason = f"High token overlap ({', '.join(intersection)})"

        if name_score < 0.5:
            return None  # Insufficient lexical similarity

        # 3. Profiling Boosts & Penalties
        profile_notes = []
        profile_mod = 0.0

        if column_profile:
            # Primary Key validation
            if prop.is_primary_key:
                unique_pct = column_profile.get("unique_percentage", 0.0)
                null_cnt = column_profile.get("null_count", 0)
                warnings = column_profile.get("quality_warnings", [])

                if unique_pct >= 99.0 and null_cnt == 0:
                    profile_mod += 0.05
                    profile_notes.append("100% unique and non-null values (verified primary key candidate)")
                elif "POTENTIAL_PRIMARY_KEY" in warnings:
                    profile_mod += 0.05
                    profile_notes.append("Profile flagged column as potential primary key")
                else:
                    profile_mod -= 0.20
                    profile_notes.append("Column has non-unique or null values, suboptimal for primary key")

            # Nullability check
            if not prop.is_nullable:
                null_pct = column_profile.get("null_percentage", 0.0)
                if null_pct > 0.0:
                    profile_mod -= 0.10
                    profile_notes.append(f"Column contains {null_pct:.1f}% nulls for non-nullable property")

        # 4. Final Confidence Score (bounded 0.0 to 1.0)
        raw_confidence = (name_score * 0.70) + (type_weight * 0.30) + profile_mod
        confidence = round(max(0.0, min(1.0, raw_confidence)), 2)

        if confidence < 0.50:
            return None

        # Build composite explanation
        explanation_parts = [match_reason, type_expl]
        if profile_notes:
            explanation_parts.extend(profile_notes)
        full_explanation = ". ".join(explanation_parts) + "."

        return CandidateSuggestion(
            property_id=str(prop.id),
            property_name=prop.name,
            column_name=col_name,
            confidence=confidence,
            is_compatible=type_weight > 0.0,
            explanation=full_explanation,
        )

    @classmethod
    def discover_mappings_for_object(
        cls,
        business_object_properties: list[Property],
        dataset_schema: list[dict[str, Any]],
        profiling_columns: list[dict[str, Any]] | None = None,
    ) -> list[CandidateSuggestion]:
        """Propose best candidate mappings from dataset columns to business object properties.

        Guarantees that suggestions remain candidates and are never automatically confirmed.
        """
        # Index profiles by column name for fast lookup
        profile_map: dict[str, dict[str, Any]] = {}
        if profiling_columns:
            for p in profiling_columns:
                c_name = p.get("column_name")
                if c_name:
                    profile_map[c_name] = p

        suggestions: list[CandidateSuggestion] = []

        for prop in business_object_properties:
            best_cand: CandidateSuggestion | None = None
            for col in dataset_schema:
                col_name = col.get("name", "")
                profile = profile_map.get(col_name)
                cand = cls.match_column_to_property(prop, col, profile)
                if cand and (best_cand is None or cand.confidence > best_cand.confidence):
                    best_cand = cand

            if best_cand:
                suggestions.append(best_cand)

        # Sort suggestions by confidence descending
        suggestions.sort(key=lambda s: s.confidence, reverse=True)
        return suggestions
